​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
​
        List<String> records = new ArrayList<>();
        Map<String, Record> lastRecordMap = new HashMap<>();
        Set<Integer> abnormalIndices = new TreeSet<>();
​
        for (int i = 0; i < n; i++) {
            String s = scanner.nextLine();
            records.add(s);
            String[] parts = s.split(",");
​
            String id = parts[0];
            int time = Integer.parseInt(parts[1]);
            int distance = Integer.parseInt(parts[2]);
            String actualDevice = parts[3];
            String registeredDevice = parts[4];
​
            Record record = new Record(id, time, distance, actualDevice, registeredDevice, i);
​
            // 条件 1: 设备号异常
            if (!actualDevice.equals(registeredDevice)) {
                abnormalIndices.add(i);
            }
​
            // 条件 2: 时间 & 距离异常
            if (lastRecordMap.containsKey(id)) {
                Record lastRecord = lastRecordMap.get(id);
                if ((time - lastRecord.time < 60) && (Math.abs(distance - lastRecord.distance) > 5)) {
                    abnormalIndices.add(i);
                    abnormalIndices.add(lastRecord.idx);
                }
            }
​
            lastRecordMap.put(id, record);
        }
​
        if (abnormalIndices.isEmpty()) {
            System.out.println("null");
        } else {
            List<String> output = new ArrayList<>();
            for (int idx : abnormalIndices) {
                output.add(records.get(idx));
            }
            System.out.println(String.join(";", output));
        }
    }
}
