    if (n === null) {
        n = parseInt(line.trim(), 10);
    } else {
        records.push(line.trim());
        const parts = line.trim().split(",");
​
        let id = parts[0];
        let time = parseInt(parts[1], 10);
        let distance = parseInt(parts[2], 10);
        let actualDevice = parts[3];
        let registeredDevice = parts[4];
​
        const record = { id, time, distance, actualDevice, registeredDevice, idx: records.length - 1 };
​
        // 条件 1: 设备号异常
        if (actualDevice !== registeredDevice) {
            abnormalIndices.add(record.idx);
        }
​
        // 条件 2: 时间 & 距离异常
        if (lastRecordMap.has(id)) {
            const lastRecord = lastRecordMap.get(id);
            if ((time - lastRecord.time < 60) && (Math.abs(distance - lastRecord.distance) > 5)) {
                abnormalIndices.add(record.idx);
                abnormalIndices.add(lastRecord.idx);
