package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
type Record struct {
    id                 string
    time, distance, idx int
    actualDevice, registeredDevice string
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取 N
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    records := make([]string, n)
    lastRecordMap := make(map[string]Record)
    abnormalIndices := make(map[int]bool)
​
    for i := 0; i < n; i++ {
        scanner.Scan()
        line := scanner.Text()
        records[i] = line
        parts := strings.Split(line, ",")
​
        id := parts[0]
        time, _ := strconv.Atoi(parts[1])
        distance, _ := strconv.Atoi(parts[2])
        actualDevice := parts[3]
        registeredDevice := parts[4]
​
        record := Record{id, time, distance, i, actualDevice, registeredDevice}
​
        // 条件 1: 设备号异常
        if actualDevice != registeredDevice {
            abnormalIndices[i] = true
        }
​
        // 条件 2: 时间 & 距离异常
        if lastRecord, exists := lastRecordMap[id]; exists {
            if (time - lastRecord.time < 60) && (abs(distance - lastRecord.distance) > 5) {
                abnormalIndices[i] = true
                abnormalIndices[lastRecord.idx] = true
            }
        }
​
        lastRecordMap[id] = record
    }
​
    // 输出异常记录
    if len(abnormalIndices) == 0 {
        fmt.Println("null")
    } else {
        var result []string
        for i := 0; i < n; i++ {
            if abnormalIndices[i] {
                result = append(result, records[i])
            }
        }
        fmt.Println(strings.Join(result, ";"))
    }
}
